// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 amount) public {
        // Owner of c is address(this) (deployer). Keep the domain wide: any positive balance.
        amount = bound(amount, 1, type(uint96).max);
        vm.deal(address(c), amount);

        // Owner calls withdraw(). In the reference, either the call reverts (e.g. the
        // transfer to Owner is refused) or it succeeds having drained the contract.
        bool ok;
        vm.prank(address(this));
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a completed owner withdraw() never leaves ether in c.
        // Reference: ok == false (transfer refused) or balance == 0 (drained) for every amount.
        // Mutant: withdraw succeeds for every amount while address(c).balance stays == amount > 0.
        assertTrue(!ok || address(c).balance == 0);
    }
}
